"""SETUP_REPORT.md: what `callshield init` wrote and which gated features are on or off.

Contains NO secrets.
"""

from __future__ import annotations

from callshield.cli.answers import Answers
from callshield.configreg.gates import RISKY_FEATURES
from callshield.providers.base import ProviderProfile


def _verified_text(profile: ProviderProfile) -> str:
    return "verified" if profile.verified else "UNVERIFIED template"


def render_report(ans: Answers, profile: ProviderProfile, files: list[str]) -> str:
    lines = [
        "# CallShield setup report",
        "",
        "Generated by `callshield init`. Contains no secrets. Not legal advice.",
        "",
        "## Gated features",
        "",
        "| Feature | Status | Related gates |",
        "|---|---|---|",
    ]
    for f in RISKY_FEATURES:
        status = "ON" if ans.features.get(f.key) else "off"
        lines.append(f"| {f.title} (`{f.env_var}`) | {status} | {f.gates} |")
    lines += ["", "## Setup", ""]
    lines += [
        f"- Environment: {ans.environment}",
        f"- Database: {ans.db_url.split('://', 1)[0]}",
        f"- Jurisdiction: {ans.jurisdiction} (informational; counsel has not reviewed it)",
        f"- Timezone: {ans.timezone}",
        f"- Provider profile: `{profile.id}` ({_verified_text(profile)})",
        f"- Speech-to-text: {ans.stt_engine}; text-to-speech: {ans.tts_engine}",
    ]
    if profile.acceptable_use_url:
        lines.append(f"- Provider acceptable-use terms (read them): {profile.acceptable_use_url}")
    if ans.enabled_keys():
        lines += [
            "",
            "Acknowledgment-v1 items were accepted in the wizard. This does NOT replace",
            "the in-app acknowledgment record each user must make.",
        ]
    lines += ["", "## Files written", ""] + [f"- `{name}`" for name in files]
    lines += [
        "",
        "## Next steps",
        "",
        "1. `callshield doctor`",
        "2. `callshield db upgrade`",
        "3. `callshield user create-admin` (if you skipped it)",
        "4. `callshield run api`, then open the dashboard Setup page.",
        "5. Before real calls: docs/deployment/going-live-checklist.md",
        "",
    ]
    return "\n".join(lines)
